// =============================================
// STEP 1: Get all open positions from Bybit
// =============================================
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

// Get futures positions
let positions = [];
try {
  const posResp = await signedGet.call(this, '/v5/position/list', {
    category: 'linear', settleCoin: 'USDT'
  });
  if (posResp.retCode === 0) {
    positions = (posResp.result?.list || []).filter(p => parseFloat(p.size) > 0);
  }
} catch(e) { /* no positions */ }

// Get open spot orders
let spotOrders = [];
try {
  const ordResp = await signedGet.call(this, '/v5/order/realtime', {
    category: 'spot', settleCoin: 'USDT'
  });
  if (ordResp.retCode === 0) {
    spotOrders = ordResp.result?.list || [];
  }
} catch(e) { /* no orders */ }

if (positions.length === 0 && spotOrders.length === 0) {
  return []; // No positions — skip execution
}

const allPositions = positions.map(p => ({
  symbol: p.symbol,
  side: p.side,
  size: parseFloat(p.size),
  entryPrice: parseFloat(p.avgPrice),
  markPrice: parseFloat(p.markPrice),
  unrealizedPnl: parseFloat(p.unrealisedPnl),
  stopLoss: parseFloat(p.stopLoss || '0'),
  takeProfit: parseFloat(p.takeProfit || '0'),
  category: 'linear',
  baseUrl
}));

return allPositions.map(p => ({ json: p }));

// =============================================
// STEP 2: Fetch current candles for position
// =============================================
const cfg = $getWorkflowStaticData('global');
const pos = $input.first().json;
const baseUrl = pos.baseUrl;

// Fetch 15m candles for the position's symbol
let candles15m = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/v5/market/kline?category=${pos.category}&symbol=${pos.symbol}&interval=15&limit=30`
  });
  if (resp.retCode === 0) {
    candles15m = resp.result.list.map(c => ({
      t: parseInt(c[0]), o: parseFloat(c[1]), h: parseFloat(c[2]),
      l: parseFloat(c[3]), c: parseFloat(c[4]), v: parseFloat(c[5])
    })).reverse();
  }
} catch(e) {}

// Calculate basic metrics
const riskPerUnit = Math.abs(pos.entryPrice - pos.stopLoss);
const profitPerUnit = pos.side === 'Buy' 
  ? pos.markPrice - pos.entryPrice 
  : pos.entryPrice - pos.markPrice;
const rMultiple = riskPerUnit > 0 ? profitPerUnit / riskPerUnit : 0;

return [{
  json: {
    ...pos,
    candles15m,
    riskPerUnit,
    profitPerUnit,
    rMultiple,
    pnlPercent: ((profitPerUnit / pos.entryPrice) * 100).toFixed(2)
  }
}];

// =============================================
// STEP 3: Claude analyzes position management
// =============================================
const cfg = $getWorkflowStaticData('global');
const pos = $input.first().json;

const SYSTEM_PROMPT = `Ты — профессиональный трейдер по системе Герчика.
Ты управляешь открытой позицией и принимаешь решение о действиях.

ПРАВИЛА УПРАВЛЕНИЯ ПОЗИЦИЕЙ:
1) Если цена прошла 1R в прибыль — перенеси стоп в безубыток.
2) Если цена достигла TP1 — зафиксируй 30% позиции.
3) Если цена достигла TP2 — зафиксируй ещё 30% позиции.
4) Если цена достигла TP3 — закрой позицию полностью.
5) Если структура рынка изменилась (пробой уровня против позиции) — закрой позицию.
6) Если объём резко вырос против позиции — закрой позицию.

ФОРМАТ ОТВЕТА строго JSON:
{
  "action": "HOLD|MOVE_STOP|PARTIAL_CLOSE|FULL_CLOSE",
  "new_stop_loss": number или null,
  "close_percent": 0-100,
  "reasoning": "краткое объяснение на русском",
  "urgency": "low|medium|high"
}

ВАЖНО: Отвечай ТОЛЬКО валидным JSON.`;

const userMsg = `Позиция: ${pos.side} ${pos.symbol}
Вход: ${pos.entryPrice}
Текущая цена: ${pos.markPrice}
Стоп-лосс: ${pos.stopLoss}
Тейк-профит: ${pos.takeProfit}
Размер: ${pos.size}
Нереализованный P&L: $${pos.unrealizedPnl.toFixed(2)} (${pos.pnlPercent}%)
R-множитель: ${pos.rMultiple.toFixed(2)}R

Последние 15m свечи:
${JSON.stringify(pos.candles15m.slice(-10))}

Что делать с позицией?`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${cfg.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: cfg.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514',
      max_tokens: 512,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userMsg }
      ]
    }
  });

  const text = response.choices[0].message.content;
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1];
  const decision = JSON.parse(jsonStr.trim());

  return [{ json: { ...pos, _decision: decision } }];
} catch(e) {
  // Claude unavailable — HOLD (don't make changes)
  return [{
    json: {
      ...pos,
      _decision: {
        action: 'HOLD',
        reasoning: `OpenRouter API error: ${e.message}`,
        urgency: 'low'
      }
