// STEP 4: Execute position management action
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;
const decision = data._decision;
const crypto = require('crypto');

const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;

async function signedPost(endpoint, body) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const bodyStr = JSON.stringify(body);
  const preSign = timestamp + apiKey + recvWindow + bodyStr;
  const signature = crypto.createHmac('sha256', apiSecret).update(preSign).digest('hex');
  return this.helpers.httpRequest({
    method: 'POST',
    url: `${data.baseUrl}${endpoint}`,
    headers: {
      'X-BAPI-API-KEY': apiKey, 'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp, 'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body
  });
}

let result = { action: decision.action, success: false };

try {
  if (decision.action === 'MOVE_STOP' && decision.new_stop_loss) {
    // Move stop loss
    const resp = await signedPost.call(this, '/v5/position/trading-stop', {
      category: data.category,
      symbol: data.symbol,
      stopLoss: decision.new_stop_loss.toString(),
      tpslMode: 'Full'
    });
    result.success = resp.retCode === 0;
    result.newStopLoss = decision.new_stop_loss;
    result.retMsg = resp.retMsg;
  }

  if (decision.action === 'PARTIAL_CLOSE' && decision.close_percent > 0) {
    // Close partial position
    const closeQty = (data.size * decision.close_percent / 100).toFixed(6);
    const closeSide = data.side === 'Buy' ? 'Sell' : 'Buy';
    const resp = await signedPost.call(this, '/v5/order/create', {
      category: data.category,
      symbol: data.symbol,
      side: closeSide,
      orderType: 'Market',
      qty: closeQty,
      reduceOnly: true
    });
    result.success = resp.retCode === 0;
    result.closedQty = closeQty;
    result.closePercent = decision.close_percent;
    result.retMsg = resp.retMsg;
  }

  if (decision.action === 'FULL_CLOSE') {
    // Close entire position
    const closeSide = data.side === 'Buy' ? 'Sell' : 'Buy';
    const resp = await signedPost.call(this, '/v5/order/create', {
      category: data.category,
      symbol: data.symbol,
      side: closeSide,
      orderType: 'Market',
      qty: data.size.toString(),
      reduceOnly: true
    });
    result.success = resp.retCode === 0;
    result.retMsg = resp.retMsg;
  }
} catch(e) {
  result.error = e.message;
}

return [{ json: { ...data, _result: result } }];

// Format notification
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;
const d = data._decision;
const r = data._result;

const actionEmoji = {
  'MOVE_STOP': '🔄', 'PARTIAL_CLOSE': '📊', 'FULL_CLOSE': '🏁'
};
const urgencyEmoji = { 'low': '🟢', 'medium': '🟡', 'high': '🔴' };

let msg = `${actionEmoji[d.action] || '📋'} <b>Position Manager</b>\n\n`;
msg += `<b>${data.side} ${data.symbol}</b>\n`;
msg += `<b>Действие:</b> ${d.action}\n`;
msg += `<b>Срочность:</b> ${urgencyEmoji[d.urgency] || ''} ${d.urgency}\n\n`;
msg += `<b>Вход:</b> <code>${data.entryPrice}</code>\n`;
msg += `<b>Цена:</b> <code>${data.markPrice}</code>\n`;
msg += `<b>P&L:</b> $${data.unrealizedPnl.toFixed(2)} (${data.pnlPercent}%)\n`;
msg += `<b>R:</b> ${data.rMultiple.toFixed(2)}\n\n`;

if (d.action === 'MOVE_STOP') {
  msg += `<b>Стоп:</b> ${data.stopLoss} → <code>${d.new_stop_loss}</code>\n`;
}
if (d.action === 'PARTIAL_CLOSE') {
  msg += `<b>Закрыто:</b> ${d.close_percent}% (${r.closedQty})\n`;
}

msg += `\n<b>Результат:</b> ${r.success ? '✅' : '❌ ' + (r.retMsg || r.error)}\n`;
msg += `<b>Причина:</b> ${d.reasoning}\n`;
msg += `\n⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message: msg } }];
